import {materials} from '../../core/index.js';
import {printedArtwork} from '../../modeling/artwork.js';
import {THREE,outline,hole,solid,ring,mesh,box} from './geometry.js';
import {spec,edgeBores,leadDrills} from './dimensions.js';
import {socket} from './connectors.js';
import {emitters} from './leds.js';
const rearUrl=new URL('./artwork/rear.png',import.meta.url).href;
function board(host){const shape=outline(spec.pcb.vertices);for(const[x,y]of edgeBores)hole(shape,x,y,.32);for(const[x,y]of leadDrills)hole(shape,x,y,.33);const pcb=mesh(host.body,solid(shape,1),materials.plastic(0x20251f,{roughness:.9}),[0,0,-.5],'Original A045 closed1mm hexagonal PCB with real18edge bores and12retained lead drills');pcb.userData={role:'physical-pcb',source:'Own A045 dimensional/photo reconstruction;no native or A045-B geometry'};const tin=materials.metal(0xb3b8a9,{roughness:.48}),edgePads=[],barrels=[],pads=[],solder=[];for(const[x,y]of edgeBores){barrels.push(mesh(host.body,ring(.335,.32,1),tin,[x,y,-.5],'A045 real plated edge bore wall'));for(const z of[-.525,.5])edgePads.push(mesh(host.body,ring(.5,.32,.025),tin,[x,y,z],'A045 actual round exposed edge copper'));}for(const[x,y]of leadDrills){for(const z of[-.55,.5])pads.push(mesh(host.body,ring(.57,.33,.05),tin,[x,y,z],'A045 real through-board connector solder land'));solder.push(mesh(host.body,ring(.5,.18,.16),tin,[x,y,-.71],'A045 real rear connector solder retention collar'));}
 const capacitors=[],ends=[],locations=[...[-7.5,-2.5,2.5,7.5].map(x=>[x,13]),...[-10,-5,0,5,10].map(x=>[x,8.66]),[-10,-8.66],[-6.8,-8.66],[6.8,-8.66],[10,-8.66],[-7.5,-13],[7.5,-13],[2.5,5.45],[-2.5,5.45]];for(const[i,[x,y]]of locations.entries()){const horizontal=i>=15;capacitors.push(box(host.body,horizontal?[1.75,.75,.7]:[.75,1.75,.7],[x,y,-.85],materials.plastic(0xa19a83,{roughness:.8}),'A045 fixed visible rear passive '+(i+1)+';photo envelope/no invented value'));for(const sign of[-1,1])ends.push(box(host.body,horizontal?[.32,.85,.5]:[.85,.32,.5],[x+(horizontal?sign*.76:0),y+(horizontal?0:sign*.76),-.75],tin,'A045 real rear passive metal solder end'));}
 return{pcb,edgePads,barrels,pads,solder,capacitors,ends,edgeBores,leadDrills};}
export function buildHEX(host){const circuit=board(host),input=socket(host,'grove'),output=socket(host,'out'),power=socket(host,'power'),display=emitters(host),codeFilm=box(host.body,[...spec.codeFilm.size,spec.codeFilm.thicknessMm],spec.codeFilm.position,materials.plastic(0xf4f1e4,{roughness:.85}),'A045 original individual code physical white carrier;QR/0005 ink omitted');codeFilm.userData={role:'physical-label-substrate',individualInkOmitted:true,thicknessMm:.06,registrationInferred:true};const ink=printedArtwork(host,{target:circuit.pcb,url:rearUrl,size:[36,31.2],position:[0,0,-.5],face:'back',depth:.12,name:'Original A045 actual HEXv1.1 IN OUT PCB silkscreen code redraw',artworkKind:'reference-redraw'});host.hexAssembly={frame:circuit.pcb.parent,board:circuit,input,output,power,display,codeFilm,ink};host.unitStickers=ink??[];}
